    # Start with staying in place.
    dx = 0
    dy = 0

    # Helper: distance to a target (Manhattan)
    def manhattan(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    # 1) If there is a nearby resource, try to move toward it (first resource in list)
    if resources:
        rx = resources[0].get("x", x)
        ry = resources[0].get("y", y)
        if rx is not None and ry is not None:
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            # if same x, adjust y
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            # normalize if both set
            if dx != 0 and dy != 0:
                return [dx, dy]

    # 2) Avoid nearest enemy: move away if an enemy is adjacent
    if enemies:
        # pick closest enemy
        best = None
        bestd = 9999
        ex, ey = None, None
        for e in enemies:
            ex = e.get("x", x)
            ey = e.get("y", y)
            d = manhattan(x, y, ex, ey)
            if d < bestd:
                bestd = d
                best = (ex, ey)
        if best is not None:
            ex, ey = best
            # if enemy is adjacent or on us, try to step away
            if bestd <= 2:
                if ex > x:
                    dx = -1
                elif ex < x:
                    dx = 1
                if ey > y:
                    dy = -1
                elif ey < y:
                    dy = 1
                # if both advisable, ensure within bounds by clamping later
