                fx += f.get("x", x)
                fy += f.get("y", y)
                count += 1
        if count:
            fx //= count
            fy //= count
            if fx > x:
                dx = 0 if dx != 0 else 1
            elif fx < x:
                dx = 0 if dx != 0 else -1
            if fy > y:
                dy = 0 if dy != 0 else 1
            elif fy < y:
                dy = 0 if dy != 0 else -1
            if dx != 0 or dy != 0:
                return [dx, dy]

    # 4) Territory/observation-based bias: try to move to center-ish of visible area
    if observation:
        # attempt to bias towards center of grid if size known
        tx = observation.get("grid_width", 0)
        ty = observation.get("grid_height", 0)
        if tx and ty:
            cx = tx // 2
            cy = ty // 2
            if cx > x:
