            elif cx < x:
                dx = -1
            if cy > y:
                dy = 1
            elif cy < y:
                dy = -1
            if dx != 0 or dy != 0:
                return [dx, dy]

    # 5) If nothing else, stay within bounds if possible
    # Clamp to valid small moves
    return [dx, dy]

